  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "Prednisolone, the closest analogue (Morgan similarity 0.6154), has an absolute oral bioavailability of 0.92 in normal subjects, directly supporting high F for the query corticosteroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Methylprednisolone, a close analogue (similarity 0.597), shows absolute oral bioavailability of 82.4% from tablets, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Hydrocortisone (similarity 0.4857) has an absolute oral bioavailability of 0.95 in healthy adults, providing additional supportive evidence for high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Dexamethasone, a related corticosteroid with lower similarity (0.3333), has mean absolute oral bioavailability of 60.7%, still well above the 20% threshold and supportive of high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Loteprednol etabonate has very low oral bioavailability, but it is a lipophilic ester prodrug with extensive presystemic hydrolysis and low structural transferability to the query; this does not outweigh the strong supportive corticosteroid evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a chlorinated corticosteroid closely related to prednisolone, methylprednisolone, and hydrocortisone, all of which have absolute oral bioavailability well above 20% (typically 60-100%). The closest analogue prednisolone has F ~0.92. The low-bioavailability analogues are structurally distant ester prodrugs or angiostatic steroids and do not outweigh the strong supportive evidence. The physicochemical prior is also favorable. Therefore, the query is predicted to have high oral bioavailability at the F >= 20% threshold.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact chlorinated query molecule.",
    "The impact of the chlorine and additional double bond on first-pass metabolism or transporter efflux is not directly evidenced.",
    "Low-bioavailability corticosteroid esters such as loteprednol etabonate and anecortave desacetate show that certain structural modifications can drastically reduce F, but their relevance to this non-ester query is limited."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

